const detailTiles=new Map(),TILE=512;
function detailTile(tx,ty){const key=tx+','+ty;if(detailTiles.has(key)){const c=detailTiles.get(key);detailTiles.delete(key);detailTiles.set(key,c);return c;}const c=document.createElement('canvas');c.width=c.height=TILE;const g=c.getContext('2d',{alpha:false}),x=tx*TILE,y=ty*TILE;g.drawImage(mapCanvas,x*CACHE_SCALE,y*CACHE_SCALE,TILE*CACHE_SCALE,TILE*CACHE_SCALE,0,0,TILE,TILE);g.translate(-x,-y);const nearby=[...roadIndex.near(x+TILE/2,y+TILE/2,TILE*.72)];for(const b of buildingIndex.near(x+TILE/2,y+TILE/2,TILE*.72))paintBuilding(g,b);g.lineCap='round';g.lineJoin='round';for(const edge of nearby)line(g,[[edge.a.x,edge.a.y],[edge.b.x,edge.b.y]],edge.road.bridge?'#c9c7b4':'#c0bdac',edge.road.width+10);for(const edge of nearby)line(g,[[edge.a.x,edge.a.y],[edge.b.x,edge.b.y]],edge.road.foot?'#b9ac92':'#424e52',edge.road.width);for(const edge of nearby)if(!edge.road.one&&!edge.road.foot&&edge.road.width>=30)line(g,[[edge.a.x,edge.a.y],[edge.b.x,edge.b.y]],'#d8cda175',1,[9,11]);detailTiles.set(key,c);if(detailTiles.size>32)detailTiles.delete(detailTiles.keys().next().value);return c;}
function drawDetail(g,sx,sy,sw,sh){for(let tx=Math.floor(sx/TILE);tx<=Math.floor((sx+sw)/TILE);tx++)for(let ty=Math.floor(sy/TILE);ty<=Math.floor((sy+sh)/TILE);ty++)if(tx>=0&&ty>=0&&tx*TILE<WORLD&&ty*TILE<WORLD)g.drawImage(detailTile(tx,ty),tx*TILE,ty*TILE);const labels=new Map();for(const edge of roadIndex.near(camera.x,camera.y,Math.max(W,H)/zoom/2)){if(!edge.road.name||edge.length<65)continue;const p={x:(edge.a.x+edge.b.x)/2,y:(edge.a.y+edge.b.y)/2};if(!visible(p,0))continue;const old=labels.get(edge.road.name);if(!old||dist(p,camera)<dist(old.p,camera))labels.set(edge.road.name,{edge,p});}for(const [name,{edge,p}] of labels){let a=Math.atan2(edge.b.y-edge.a.y,edge.b.x-edge.a.x);if(Math.abs(a)>Math.PI/2)a+=Math.PI;g.save();g.translate(p.x,p.y);g.rotate(a);g.font='bold 8px Arial';g.textAlign='center';const width=g.measureText(name.toUpperCase()).width;rect(g,-width/2-3,-edge.road.width/2-13,width+6,11,'#263a35b0');textAt(g,name.toUpperCase(),0,-edge.road.width/2-5,8,'#e5ddc0');g.restore();}}
