function lanePosition(s,reverse,t){const a=reverse?s.b:s.a,b=reverse?s.a:s.b,vx=(b.x-a.x)/s.length,vy=(b.y-a.y)/s.length,offset=s.road.one?0:Math.min(7,s.road.width*.22);return {x:a.x+(b.x-a.x)*t-vy*offset,y:a.y+(b.y-a.y)*t+vx*offset,a:Math.atan2(vy,vx)};}
function routeNodes(start,end){if(start===end)return [start];const heap=[{id:start,cost:0,score:0}],costs=new Map([[start,0]]),prev=new Map();let count=0;while(heap.length&&count++<30000){heap.sort((a,b)=>b.score-a.score);const n=heap.pop();if(n.cost!==costs.get(n.id))continue;if(n.id===end){const route=[end];while(route[0]!==start)route.unshift(prev.get(route[0]));return route;}for(const e of graph.get(n.id)?.edges||[]){const cost=n.cost+e.segment.length;if(cost<(costs.get(e.to)??Infinity)){costs.set(e.to,cost);prev.set(e.to,n.id);heap.push({id:e.to,cost,score:cost+dist(graph.get(e.to),graph.get(end))});}}}return [];}
function roadRoute(from,to){const a=nearestRoad(from),b=nearestRoad(to);if(!a||!b)return [];const start=a.segment.road.one?a.segment.to:(dist(from,a.segment.a)<dist(from,a.segment.b)?a.segment.from:a.segment.to),end=b.segment.from;const ids=routeNodes(start,end);return ids.length?[from,{x:a.x,y:a.y},...ids.map(id=>graph.get(id)),{x:b.x,y:b.y},to]:[];}
