function chooseNext(c){const id=c.reverse?c.edge.from:c.edge.to;let opts=(graph.get(id)?.edges||[]).filter(e=>mainNodes.has(e.to));const forward=opts.filter(e=>e.segment!==c.edge);if(forward.length)opts=forward;if(!opts.length){assignEdge(c,c.edge,!c.reverse,0);return;}let choice=opts[Math.floor(rand(0,opts.length))];if(c.police&&wanted>0){if(!c.pursuit||clock>c.repath){const goal=nearestRoad(player);c.pursuit=goal?routeNodes(id,goal.segment.from):[];c.repath=clock+3;}const index=c.pursuit.indexOf(id),next=c.pursuit[index+1];choice=opts.find(e=>e.to===next)||opts.reduce((a,b)=>dist(graph.get(a.to),player)<dist(graph.get(b.to),player)?a:b);}assignEdge(c,choice.segment,choice.reverse,0);}
