let audio=null,engine=null,engineGain=null,soundOn=false,musicOn=true,musicBus=null,noiseBuffer=null,nextMusicTime=0,musicStep=0;const musicVoices=new Set();
function initAudio(){if(audio)return;try{audio=new(window.AudioContext||window.webkitAudioContext)();engine=audio.createOscillator();engine.type='sawtooth';engineGain=audio.createGain();engineGain.gain.value=0;engine.connect(engineGain);engineGain.connect(audio.destination);engine.start();musicBus=audio.createGain();musicBus.gain.value=.7;musicBus.connect(audio.destination);noiseBuffer=audio.createBuffer(1,audio.sampleRate*.15,audio.sampleRate);const samples=noiseBuffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*(1-i/samples.length);nextMusicTime=audio.currentTime+.08;}catch{}}
function tone(freq,duration=.1,type='square',volume=.03){if(!soundOn||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(25,freq*.45),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
