const leadMelody=[76,0,79,81,0,79,76,72, 74,76,0,72,71,0,69,0, 72,0,76,77,0,76,72,69, 71,72,0,69,67,0,69,0, 76,0,79,84,0,83,79,76, 74,76,79,0,76,74,72,0, 74,0,79,81,0,79,74,71, 72,74,0,71,69,0,67,0];
const chords=[[57,60,64],[53,57,60],[48,52,55],[55,59,62]];
function rememberVoice(o){musicVoices.add(o);o.onended=()=>{musicVoices.delete(o);o.disconnect();};}
function musicNote(note,at,duration,volume,type='triangle'){const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=440*Math.pow(2,(note-69)/12);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(g);g.connect(musicBus);rememberVoice(o);o.onended=()=>{musicVoices.delete(o);o.disconnect();g.disconnect();};o.start(at);o.stop(at+duration+.02);}
function drum(at,kick=false,snare=false){const g=audio.createGain();g.connect(musicBus);const o=kick?audio.createOscillator():audio.createBufferSource();if(kick){o.frequency.setValueAtTime(130,at);o.frequency.exponentialRampToValueAtTime(42,at+.15);o.connect(g);}else{o.buffer=noiseBuffer;const filter=audio.createBiquadFilter();filter.type='highpass';filter.frequency.value=snare?1500:6500;o.connect(filter);filter.connect(g);}const dur=kick?.18:snare?.12:.045;g.gain.setValueAtTime(kick?.13:snare?.075:.025,at);g.gain.exponentialRampToValueAtTime(.001,at+dur);rememberVoice(o);o.onended=()=>{musicVoices.delete(o);o.disconnect();g.disconnect();};o.start(at);o.stop(at+dur);}
function stopMusic(){for(const o of musicVoices){try{o.stop();}catch{}}musicVoices.clear();if(audio)nextMusicTime=audio.currentTime+.05;}
function pumpMusic(){if(!audio||audio.state!=='running'||!musicOn||!active)return;const eighth=60/108/2;if(nextMusicTime<audio.currentTime)nextMusicTime=audio.currentTime+.04;while(nextMusicTime<audio.currentTime+.14){const step=musicStep%64,beat=step%8,chord=chords[Math.floor(step/16)],at=nextMusicTime;if(leadMelody[step]){musicNote(leadMelody[step],at,eighth*1.7,.042);musicNote(leadMelody[step],at+eighth*.75,eighth,.011,'sine');}if(beat%2===0)musicNote(chord[0]-12+(beat===6?7:0),at,eighth*1.6,.09,'sine');if(beat===0)for(const n of chord)musicNote(n,at,eighth*7.5,.014,'triangle');if(beat===0||beat===4)drum(at,true);if(beat===2||beat===6)drum(at,false,true);drum(at);musicStep++;nextMusicTime+=eighth;}}
