function start(){if(dead){player.car=null;player.x=spawnPoint.x;player.y=spawnPoint.y;player.hp=100;wanted=0;arrest=0;invincible=5;dead=false;job=null;officers.length=0;policeBullets.length=0;navRoute=[];for(const c of cars)if(c.police){c.ai=false;c.deployed=0;}toast('Wracasz na ulice. Uważaj na ruch.');}active=true;started=true;frameTime=0;acc=0;$('overlay').style.display='none';resetInput();initAudio();if(audio&&(soundOn||musicOn)){nextMusicTime=audio.currentTime+.05;audio.resume().catch(()=>{});}}
function die(reason){if(dead)return;dead=true;active=false;cash=Math.max(0,cash-150);save();resetInput();$('overlay').style.display='flex';$('intro').textContent=reason+' Koszt powrotu: do 150 zł. Zebrana gotówka i rekord są zapisywane na tym urządzeniu.';$('play').textContent='WRÓĆ DO MIASTA →';stopMusic();if(engineGain)engineGain.gain.value=0;}
function hurt(n){if(invincible>0||dead)return;player.hp=Math.max(0,player.hp-n);invincible=.65;shake=6;if(player.hp<=0)die('Koniec przejażdżki.');}
function nearestCar(){let best=null,d=64;for(const c of cars)if(c.hp>0){const dd=dist(c,player);if(dd<d){best=c;d=dd;}}return best;}
function action(){if(!active)return;if(player.car){const c=player.car;if(Math.abs(c.s)>110){toast('Zwolnij przed wysiadaniem.');return;}for(const side of [1,-1,2]){let a=c.a+Math.PI/2*side,x=c.x+Math.cos(a)*40,y=c.y+Math.sin(a)*40;if(!blocked(x,y,10)&&!cars.some(o=>o!==c&&Math.hypot(o.x-x,o.y-y)<26)){player.x=x;player.y=y;player.car=null;c.s*=.3;invincible=1;toast('Pieszo · mysz celuje, R zmienia broń');return;}}toast('Brak miejsca. Odsuń auto od przeszkody.');return;}let c=nearestCar();if(!c){toast('Podejdź bliżej sprawnego auta.');return;}if(c.ai)crime(c.police?1.2:.55);c.ai=false;c.parked=false;player.car=c;player.x=c.x;player.y=c.y;toast(c.type.name+' · Shift / HAMULEC = ręczny');tone(160,.12,'triangle');}
function burst(x,y,color,n=10){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-75,75),vy:rand(-75,75),life:rand(.2,.6),max:.6,color});if(particles.length>260)particles.splice(0,particles.length-260);}
function damageCar(c,n){if(c.hp<=0)return;c.hp=Math.max(0,c.hp-n);if(c.hp<=0){c.ai=false;c.s=0;c.deadTime=clock;explosions.push({x:c.x,y:c.y,age:0,seed:rand(0,TAU)});if(explosions.length>18)explosions.shift();burst(c.x,c.y,'#ffcb75',42);tone(70,.4,'sawtooth',.06);shake=9;if(player.car===c){player.car=null;for(const a of [c.a+Math.PI/2,c.a-Math.PI/2,c.a+Math.PI]){let x=c.x+Math.cos(a)*48,y=c.y+Math.sin(a)*48;if(!blocked(x,y)){player.x=x;player.y=y;break;}}hurt(38);invincible=2;toast('Auto zniszczone. Znajdź następne.');}}}
function shoot(){if(!active||player.car||fireCooldown>0)return;const w=weapons[weapon];fireCooldown=w.rate;crime(.14);tone(weapon===2?85:180,.075,'sawtooth',.04);for(let i=0;i<w.count;i++){let a=player.a+rand(-w.spread,w.spread);bullets.push({x:player.x+Math.cos(a)*15,y:player.y+Math.sin(a)*15,a,life:w.life,damage:w.damage});}burst(player.x+Math.cos(player.a)*18,player.y+Math.sin(player.a)*18,'#fff1b0',3);for(const p of peds)if(dist(p,player)<230){p.panic=5;p.a=Math.atan2(p.y-player.y,p.x-player.x);}}
