function joyMove(e){const r=$('joy').getBoundingClientRect(),m=r.width*.34;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,l=Math.hypot(x,y);if(l>m){x*=m/l;y*=m/l;}input.x=x/m;input.y=y/m;$('stick').style.transform=`translate(${x}px,${y}px)`;mouseAim=false;}
