addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'&&panelOpen){closePanel();return;}if(e.code==='KeyM'){pauseForPanel('atlas');return;}if(e.code==='Escape'||e.code==='KeyP'){pause();return;}if(panelOpen)return;keys[e.code]=true;if(e.code==='KeyE')action();if(e.code==='KeyR')cycle();if(e.code==='KeyF')takeJob();});addEventListener('keyup',e=>{keys[e.code]=false;});addEventListener('blur',()=>{if(active)pause();else resetInput();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)pause();});
