let visiblePolice=cops.some(c=>dist(c,player)<430)||officers.some(o=>dist(o,player)<340&&clearPath(o,player));if(wanted>0&&clock-lastCrime>10&&!visiblePolice){wanted=Math.max(0,wanted-dt*.11);if(wanted===0){cash+=100;save();toast('POŚCIG ZGUBIONY · +100 zł');}}
let cornered=cops.some(c=>dist(c,player)<65);if(cornered&&player.car&&Math.abs(player.car.s)<35){arrest+=dt;if(arrest>=4)die('Policja Cię zatrzymała.');}else arrest=Math.max(0,arrest-dt*2);
