if(engineGain){engineGain.gain.setTargetAtTime(soundOn&&player.car ? .018 : 0,audio.currentTime,.08);engine.frequency.setTargetAtTime(player.car?45+Math.abs(player.car.s)*.6:40,audio.currentTime,.08);if(soundOn&&visiblePolice&&Math.floor(clock*3)!==Math.floor((clock-dt)*3))tone(Math.floor(clock*3)%2?650:850,.25,'sine',.016);}
